steps.expression:
(
  $month := inputs.month;
  $start := $month & "-01";
  $year := $number($substring($month,0,4));
  $m := $number($substring($month,5,2));
  $leap := $year % 400 = 0 or ($year % 4 = 0 and $year % 100 != 0);
  $days := $m = 2 ? ($leap ? 29 : 28) : ($m in [4,6,9,11] ? 30 : 31);
  $sites := {"菲律宾":"ph","马来西亚":"my","泰国":"th","越南":"vn","巴西":"br","新加坡":"sg"};
  $rates := sources.rates;
  $scope := inputs.productFilter;
  $items := sources.products[监控状态 = "监控中" and ($not($exists($scope)) or 产品名 = $scope)].(
    $product := $;
    $group := $string([产品名, 产品线, 公司]);
    $assert($boolean(产品名) and $boolean(产品线) and $boolean(公司), "监控产品缺少产品名、产品线或公司");
    $site := $lookup($sites, 国家);
    $rate := $rates[国家 = $product.国家].汇率;
    $validRate := $exists($rate) and $count([$rate]) = 1 and $contains($string($rate), /^[0-9]+(\.[0-9]+)?$/) and $number($rate) > 0;
    $ids := $split(产品ID ?? "", /[,，、;；\s]+/)[ $ != "" ];
    $not($exists($site)) or $not($validRate) or $count($ids) = 0
      ? {"group":$group,"warning":$group & "：缺少站点、汇率或商品 ID"}
      : $ids.(
          $id := $;
          $contains($id, /^[1-9][0-9]{0,14}$/)
            ? {"key":$site & "/" & $id,"site":$site,"itemId":$number($id),"idText":$id,"product":$product.产品名,
               "group":$group,"rate":$number($rate),"startDate":$start,"endDate":$month & "-" & $string($days)}
            : {"group":$group,"warning":$group & "：商品 ID 格式无效"}
        )
  );
  $valid := $items[$exists(key)];
  $unique := $map($distinct($valid.key), function($key){(
    $rows := $valid[key = $key];
    $assert($count($distinct($rows.group)) = 1,"同一站点的商品 ID 对应多个产品组");
    $rows[0]
  )});
  {"records":[$unique,$items[$exists(warning)]]}
)

(
  $month := inputs.month;
  $pages := sources.trend;
  $rows := $map($distinct($pages.input.key), function($key){(
    $parts := $pages[input.key = $key];
    $item := $parts[0].input;
    $daily := $parts.response.data;
    $invalid := $daily[$not($type(sales) = "number" and $type(gmv) = "number" and sales >= 0 and gmv >= 0 and
      itemId = $item.itemId and site = $item.site and $substring(timest,0,7) = $month)];
    $sales := $sum($daily.sales);
    $gmv := $sum($daily.gmv);
    $count($parts[$exists(error) or response.success != true]) > 0 or $count($daily) = 0 or
      $count($invalid) > 0 or $count($distinct($daily.timest)) != $count($daily) or $count($daily) != $parts[0].response.total
      ? {"group":$item.group,"warning":$key & "：接口错误、无数据或分页未收齐"}
      : {"group":$item.group,"fields":{"月份":$month,"产品ID":$item.idText,"平台":"shopee-" & $item.site,
           "产品名":$item.product,"销量":$sales,"单价":$sales > 0 ? $gmv / $sales : 0,
           "汇率":$item.rate,"销额":$gmv * $item.rate}}
  )});
  $all := [$rows,sources.candidates[$exists(warning)]];
  $assert($exists($all.fields),"没有可用的 Shopee 月度记录，请检查监控配置和接口返回");
  {"records":$all,"warnings":[$all.warning]}
)

(
  $rows := sources.monthly;
  $allowPartial := inputs.allowPartialSummary = true;
  $bad := $distinct($rows[$exists(warning)].group);
  $groups := $distinct($rows[$exists(fields)].group);
  {"records":[$map($groups[$allowPartial or $not($ in $bad)],function($key){(
    $fields := $rows[group = $key].fields;
    $group := $parseJSON($key);
    $sales := $sum($fields.销量);
    $gmv := $sum($fields.销额);
    {"月份":inputs.month,"产品名":$group[0],"产品线":$group[1],"公司":$group[2],
     "国内线上销量":$sales,"国内线上客单价":$sales > 0 ? $gmv / $sales : 0,"国内线上销额预估":$gmv}
  )})],"warnings":[$count($bad) > 0 ? ($allowPartial ? "按已获取数据计算部分汇总，涉及 " & $count($bad) & " 个不完整组" : "跳过 " & $count($bad) & " 个数据不完整的汇总组")]}
)
